const publishedCatalogue={},productRoutes={};
Object.entries(regionPages).forEach(([region,collection])=>collection.cards.forEach(item=>{
  if(!item.id||!item.type||!item.images?.[0]?.card)return;
  (publishedCatalogue[item.type]??=[]).push(item);
  productRoutes[item.type]??={page:`/collections/${region}.html`,anchor:item.type};
}));
const catalogueOrder=['dhaniakhali','gorod','phulia','baluchari','ilkal','patteda-anchu','narayanpet','dhalapathar','banarasi'];
globalThis.kiranlataProductCatalogues=Object.fromEntries(Object.entries(publishedCatalogue).sort(([a],[b])=>{
  const ai=catalogueOrder.indexOf(a),bi=catalogueOrder.indexOf(b);
  return (ai<0?Infinity:ai)-(bi<0?Infinity:bi)||a.localeCompare(b);
}));
globalThis.kiranlataProductRoutes=productRoutes;
const categoryStories={
  bengal:{
    dhaniakhali:{kicker:'Hooghly district · West Bengal',title:'The quiet rhythm of Bengal cotton',lead:'Crisp, enduring and unmistakably grounded in place.',facts:[['Cloth','Handloom cotton'],['Known for','Distinctive woven borders'],['Heritage','Geographical Indication protected']],paragraphs:[
      'Dhaniakhali is a traditional cotton handloom saree from the Hooghly district of West Bengal, with a weaving heritage that stretches back generations. Known for its crisp cotton, distinctive borders, and everyday elegance, the saree developed around the weaving communities of Dhaniakhali and the surrounding villages.',
      'Originally valued as a practical cotton saree for Bengal’s warm climate, Dhaniakhali became known for its durability, comfort, and understated beauty. Traditionally woven on handlooms, its character comes from the slight texture of the cloth and the rhythm of the woven border rather than elaborate ornamentation.',
      'Today, Dhaniakhali remains part of Bengal’s living handloom tradition and is protected by a Geographical Indication (GI) tag, recognizing its connection to the region and its weaving heritage.'
    ]}
  }
};
const editorial=(kicker,title,lead,facts,paragraphs)=>({kicker,title,lead,facts,paragraphs});
Object.assign(categoryStories.bengal,{
  gorod:editorial('Murshidabad · West Bengal','Natural silk, framed in red','A restrained Bengal silk tradition shaped by lustre, structure and colour.',[['Cloth','Handwoven pure silk'],['Signature','Cream or ivory body with a red or maroon border'],['Heritage','Garad Saree · Geographical Indication protected']],['Garad sarees are associated particularly with Murshidabad in West Bengal. Their character begins with the natural cream or ivory appearance of silk, traditionally framed by a simple red or maroon border and often completed with a striped pallu.','A lightly starched, paper-like finish gives the cloth its distinctive structure while preserving the quiet lustre of silk. Rather than relying on dense ornament, Garad places emphasis on material, proportion and the decisive contrast between body and border.']),
  baluchari:editorial('Bishnupur · Bankura district · West Bengal','A pallu that tells a story','Narrative panels and richly framed borders define Baluchari’s visual language.',[['Cloth','Narrative silk is the best-known registered form'],['Signature','Figurative pallu scenes'],['Kiranlata edit','Two cotton pieces · four pure-silk pieces']],['Baluchari is best known as a handloom silk saree whose pallu carries woven scenes from epics and mythology. The images are built into the cloth rather than printed, and are framed by decorative borders.','This Kiranlata selection includes two cotton Baluchari pieces and four pure-silk pieces. The product details keep each material and GI designation specific to its own listing; BALU-003 and BAL-004 carry the registered Baluchari Saree GI label in their product records.']),
  phulia:editorial('Fulia · Nadia district · West Bengal','Tangail lineage, woven in Bengal','Handwoven cotton shaped by migration, geometry and a living Nadia weaving centre.',[['Cloth','Handwoven pure cotton'],['Place','Fulia and the Nadia weaving belt'],['Heritage','Tangail Saree of Bengal · Geographical Indication protected']],['Tangail sarees are woven across Nadia district with an important concentration around Fulia. The weaving community includes local artisans as well as families whose knowledge travelled from Tangail in present-day Bangladesh, making the cloth part of a continuing Bengal textile lineage.','Colourful geometric compositions and clearly framed borders distinguish the tradition. This Kiranlata edit focuses on handwoven pure-cotton sarees, from doodhe-alta white and red to dark green, maroon and multicolour interpretations.']),
  kalakshetra:editorial('Bengal · Art-led handloom','The loom as a drawing surface','Folk memory and graphic rhythm meet in cloth.',[['Cloth','Cotton or cotton-silk'],['Signature','Art-led figurative motifs'],['Character','Graphic, narrative, expressive']],['Bengal Kalakshetra sarees bring an art-led sensibility to regional handloom, using woven or textile-applied motifs inspired by folk imagery, landscape and everyday cultural memory.','The emphasis is expressive rather than uniform. Borders and pallus become fields for drawing with thread, allowing each saree to carry a distinct visual voice.'])
});
categoryStories.odisha={dhalapathar:editorial('Dhalapathar village · Khordha district · Odisha','Pattern built patiently by hand','A rare cotton tradition shaped by village knowledge.',[['Cloth','Handloom cotton'],['Technique','Wooden chari and handmade cotton heald shafts'],['Heritage','Dhalapathar Parda & Fabrics · GI protected']],['Dhalapathar Parda & Fabrics takes its name from Dhalapathar village in Odisha’s Khordha district. The registered tradition is best known for handmade curtains, wall hangings and table covers woven with thick cotton threads.','Its distinctive construction uses wooden sticks known as chari together with handmade cotton heald shafts. These rare collector sarees carry the tradition’s disciplined bands, multicolor pattern and unmistakable handwoven character into wearable cloth.'])};
categoryStories['south-india']={
  ilkal:editorial('Ilkal · Bagalkot district · Karnataka','The art is in the join','Cotton, silk and graphic geometry meet at the heart of the Ilkal saree.',[['Construction','Body and pallu warps joined with loops'],['Border language','Gomi · Paraspet · Gaadi'],['Pallu character','Often red or maroon, with geometric pattern']],['Named for the weaving town of Ilkal in Karnataka’s Bagalkot district, the saree is known for a distinctive construction: the body and pallu warps are joined with a series of interlocking loops, a technique widely called Tope Teni or Kondi. Traditional descriptions also note separately prepared warp threads for the body, border and pallu.','Ilkal is not one fixed colour recipe. The body may be plain, checked or striped, while borders carry their own vocabulary—including Gomi (Ilkal Dadi), Paraspet (Chikki and Dodda Paras) and Gaadi. The pallu is often a contrasting, richly patterned end panel. The six Kiranlata pieces shown here are cotton-bodied with pure-silk pallus; individual colors and construction details appear on each product.']),
  narayanpet:editorial('Narayanpet district · Telangana','Checks, colour and a framed pallu','A light handloom cotton with a distinctive southern rhythm.',[['Cloth','Cotton and silk varieties exist'],['Signature','Checked surfaces and intricate borders'],['Heritage','Narayanpet Sarees · GI registered']],['Narayanpet sarees are made in cotton and silk varieties. Government descriptions identify the checked surface, intricate ethnic border or pallu, contrasting colour bands and small zari details as characteristic parts of the tradition.','Every saree in this Kiranlata selection is listed as pure cotton in its product information. The exact registered GI name is Narayanpet Sarees; the checked grounds, colour, and woven borders shown here describe the individual pieces rather than a single fixed recipe.']),
  'patteda-anchu':editorial('Gajendragad · Gadag district · Karnataka','Checks, framed by an anchu','A checked cotton saree tradition from North Karnataka, with ceremonial roots.',[['Cloth','Cotton handloom'],['Signature','Checked body · defining border band'],['Tradition','Wedding textile · Yellamma offering']],['Patteda Anchu is associated with Gajendragad in Karnataka’s Gadag district. The tradition is known for checked cotton grounds and a distinct border band; colors and layouts vary across sarees.','Historical and craft accounts describe Patteda Anchu sarees as wedding garments and offerings to Goddess Yellamma at Saundatti. Kiranlata’s PAT-01 is a pure-cotton black-and-ivory checked saree with a charcoal border and fine white stripes. The product listing does not make an item-specific GI claim.'])
};
categoryStories.banarasi={banarasi:editorial('Varanasi · Uttar Pradesh','A garden drawn in silk and zari','Lustre, density and extraordinary brocade skill.',[['Cloth','Silk brocade'],['Signature','Zari, jaal and butidar patterning'],['Heritage','Geographical Indication protected']],['Banarasi sarees are woven in and around Varanasi and are celebrated for richly structured brocade. Floral jaals, individual butis and metallic zari are organized through techniques that can range from delicate to architectural.','The finest examples reveal their complexity gradually: first as lustre and pattern, then as a close conversation between ground cloth, supplementary threads and the disciplined hand of the weaver.'])};
categoryStories.kanchipuram={kanchipuram:editorial('Kanchipuram · Tamil Nadu','Silk with architectural presence','Temple geometry, saturated colour and the strength of korvai.',[['Cloth','Mulberry silk'],['Signature','Contrast korvai border'],['Heritage','Geographical Indication protected']],['Kanchipuram sarees are known for substantial silk, saturated colour and borders that often echo the geometry of temple architecture. In korvai construction, contrasting sections are joined with exceptional control.','The result is both visual and structural: a saree with weight, clarity and a pallu designed to hold its presence across generations.'])};
categoryStories.maheshwari={maheshwari:editorial('Maheshwar · Madhya Pradesh','Lightness framed by geometry','Reversible borders and an elegant silk-cotton balance.',[['Cloth','Silk-cotton'],['Signature','Reversible border and striped pallu'],['Character','Light, polished, architectural']],['Maheshwari sarees are associated with the weaving town of Maheshwar and are valued for their light silk-cotton body, fine stripes, checks and elegantly controlled borders.','Many examples use a reversible border, giving both sides a finished appearance. The weave feels refined without heaviness, carrying the measured geometry of its place of origin.'])};
const mastCopy={
  bengal:{
    gorod:['Murshidabad · West Bengal','Gorod','Natural cream or ivory silk, a lightly structured finish and a traditional red or maroon border give Garad its quiet distinction.'],
    dhaniakhali:['Dhaniakhali · Hooghly district · West Bengal','Dhaniakhali','Crisp handloom cotton and distinctive woven borders carry the everyday elegance of Dhaniakhali and its surrounding weaving villages.'],
    baluchari:['Baluchar, Murshidabad · Bishnupur, Bankura · West Bengal','Baluchari','Originating in Baluchar and now strongly associated with Bishnupur, Baluchari silk turns the pallu into a field of woven narrative.'],
    phulia:['Fulia · Nadia district · West Bengal','Phulia Tangail','Handwoven cotton, colourful geometry and the continuity of Tangail weaving knowledge distinguish Fulia’s living Nadia tradition.'],
    kalakshetra:['West Bengal · Art-led handloom','Bengal Kalakshetra','An expressive, art-led strand of Bengal handloom in which folk memory, botanical forms and graphic storytelling meet cloth.']
  },
  odisha:{dhalapathar:['Dhalapathar village · Khordha district · Odisha','Dhalapathar','A rare cotton tradition using wooden chari and handmade cotton heald shafts to build distinctive multicolor pattern.']},
  'south-india':{
    ilkal:['Ilkal · Bagalkot district · Karnataka','Ilkal','A pure-cotton body, pure-silk pallu and the distinctive Tope Teni join—shown here in six individual colour stories.'],
    narayanpet:['Narayanpet district · Telangana','Narayanpet','Checked surfaces, contrast colour and intricate woven borders or pallus give Narayanpet cotton its distinctive rhythm.'],
    'patteda-anchu':['Gajendragad · Gadag district · Karnataka','Patteda Anchu','Checked cotton, a defining border band and a tradition with deep ceremonial roots in North Karnataka.']
  },
  banarasi:{banarasi:['Varanasi and its surrounding weaving region · Uttar Pradesh','Banarasi','Rich brocade, floral jaals, butis and metallic zari reflect the disciplined weaving culture of Varanasi and nearby centres.']},
  kanchipuram:{kanchipuram:['Kanchipuram · Tamil Nadu','Kanchipuram','Substantial silk, saturated colour and structurally joined borders give Kanchipuram sarees their architectural presence.']},
  maheshwari:{maheshwari:['Maheshwar · Madhya Pradesh','Maheshwari','Light silk-cotton, restrained geometry and reversible borders carry the refined weaving identity of Maheshwar.']}
};
